INSERT INTO `ec_products` VALUES (1,'EcoTech Marine Radion XR30w G5 Pro LED Light Fixture','ecotech-marine-radion-xr30w-g5-pro-led-light-fixture','Elevate your experience with industry-leading technology packed into an elegant design. Every component has been carefully selected and optimized to deliver superior performance, exceptional comfort, and unmatched durability.','<div class=\"row justify-content-center\">\n    <div class=\"col-xl-10\">\n        <div class=\"tp-product-details-desc-item pb-105\">\n            <div class=\"row align-items-center\">\n                <div class=\"col-lg-6\">\n                    <div class=\"pt-25\">\n                        <span class=\"text-muted text-uppercase fs-6 fw-medium\">Premium Technology</span>\n                        <h3 class=\"tp-product-details-desc-title\">Experience the Difference</h3>\n                        <p>\n                            Engineered with precision and designed for excellence, this product delivers outstanding performance that exceeds expectations. Every detail has been carefully considered to provide you with an exceptional experience, from the premium build quality to the intuitive interface that puts control at your fingertips.\n                        </p>\n                    </div>\n                    <div class=\"mt-4\">\n                        <h3 class=\"tp-product-details-desc-title\">Innovative Design</h3>\n                        <p>\n                            Where form meets function. The sleek, modern aesthetic complements any environment while the ergonomic design ensures comfort during extended use. Advanced materials provide durability without compromising on style, creating a product that\'s as beautiful as it is practical.\n                        </p>\n                    </div>\n                </div>\n                <div class=\"col-lg-6\">\n                    <div class=\"tp-product-details-desc-thumb\">\n                        <img src=\"/storage/main/products/product-details-desc-1.jpg\" alt=\"Premium technology design\">\n                    </div>\n                </div>\n            </div>\n        </div>\n        <div class=\"tp-product-details-desc-item pb-75\">\n            <div class=\"row align-items-center\">\n                <div class=\"col-lg-7\">\n                    <div class=\"tp-product-details-desc-thumb\">\n                        <img src=\"/storage/main/products/product-details-desc-2.jpg\" alt=\"Advanced features showcase\">\n                    </div>\n                </div>\n                <div class=\"col-lg-5 order-first order-lg-last\">\n                    <div class=\"des-content-2 pl-40\">\n                        <h3 class=\"tp-product-details-desc-title\">Built for Performance</h3>\n                        <p>\n                            Push boundaries with cutting-edge technology that delivers seamless performance when you need it most. Whether you\'re working on demanding projects, enjoying immersive entertainment, or tackling everyday tasks, experience speed and responsiveness that keeps pace with your ambitions.\n                        </p>\n                        <ul class=\"mt-3 ps-3\">\n                            <li class=\"mb-2\">High-performance processing</li>\n                            <li class=\"mb-2\">Energy-efficient operation</li>\n                            <li class=\"mb-2\">Long-lasting reliability</li>\n                        </ul>\n                    </div>\n                </div>\n            </div>\n        </div>\n        <div class=\"tp-product-details-desc-item\">\n            <div class=\"row\">\n                <div class=\"col-xl-12\">\n                    <div class=\"tp-product-details-desc-banner text-center m-img\">\n                        <h3 class=\"tp-product-details-desc-banner-title tp-product-details-desc-title\">Performance • Quality • Innovation</h3>\n                        <img src=\"/storage/main/products/product-details-desc-3.jpg\" alt=\"Technology innovation workspace\">\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n','published','[\"main\\/products\\/product-9.jpg\",\"main\\/products\\/product-10.jpg\",\"main\\/products\\/product-details-desc-1.jpg\"]','[]','Z6-112',0,14,0,1,'in_stock',0,0,NULL,NULL,2,0,0,9,3.33,0,1746,1538,NULL,NULL,20,18,14,529,NULL,'standard',131143,'2026-10-03 15:29:29','2026-10-03 15:29:45',6,0,'Botble\\ACL\\Models\\User',0,NULL,'physical','2759236875835',NULL,NULL,0,0,'auto_generate',0,0,0,2,NULL),(2,'Philips Hue White and Color Ambiance A19 LED Smart Bulb','philips-hue-white-and-color-ambiance-a19-led-smart-bulb','Transform your daily routine with this state-of-the-art solution. Featuring intelligent functionality and seamless connectivity, it integrates effortlessly into your lifestyle while delivering powerful performance when you need it most.','<div class=\"row justify-content-center\">\n    <div class=\"col-xl-10\">\n        <div class=\"tp-product-details-desc-item pb-105\">\n            <div class=\"row align-items-center\">\n                <div class=\"col-lg-6\">\n                    <div class=\"pt-25\">\n                        <span class=\"text-muted text-uppercase fs-6 fw-medium\">Premium Technology</span>\n                        <h3 class=\"tp-product-details-desc-title\">Experience the Difference</h3>\n                        <p>\n                            Engineered with precision and designed for excellence, this product delivers outstanding performance that exceeds expectations. Every detail has been carefully considered to provide you with an exceptional experience, from the premium build quality to the intuitive interface that puts control at your fingertips.\n                        </p>\n                    </div>\n                    <div class=\"mt-4\">\n                        <h3 class=\"tp-product-details-desc-title\">Innovative Design</h3>\n                        <p>\n