INSERT INTO `galleries_translations` VALUES ('ar',1,'مثالي','رحلة فنية عبر الألوان والأنسجة واللحظات المجمدة في الزمن.'),('ar',2,'يوم جديد','مجموعة مذهلة من الصور تلتقط جوهر التصميم الحديث والجمال الطبيعي.'),('ar',3,'يوم سعيد','صور عالية الجودة تعرض الحرفية والاهتمام بالتفاصيل.'),('ar',4,'الطبيعة','رحلة فنية عبر الألوان والأنسجة واللحظات المجمدة في الزمن.'),('ar',5,'الصباح','صور عالية الجودة تعرض الحرفية والاهتمام بالتفاصيل.'),('fr',1,'Parfait','Un voyage artistique à travers les couleurs, les textures et les moments figés dans le temps.'),('fr',2,'Nouveau Jour','Une superbe collection d\'images capturant l\'essence du design moderne et de la beauté naturelle.'),('fr',3,'Jour Heureux','Images de qualité supérieure mettant en valeur l\'artisanat et l\'attention aux détails.'),('fr',4,'Nature','Un voyage artistique à travers les couleurs, les textures et les moments figés dans le temps.'),('fr',5,'Matin','Images de qualité supérieure mettant en valeur l\'artisanat et l\'attention aux détails.'),('id',1,'Sempurna','Perjalanan artistik melalui warna, tekstur, dan momen yang membeku dalam waktu.'),('id',2,'Hari Baru','Koleksi gambar menakjubkan yang menangkap esensi desain modern dan keindahan alami.'),('id',3,'Hari Bahagia','Gambar berkualitas premium yang menampilkan keahlian dan perhatian terhadap detail.'),('id',4,'Alam','Perjalanan artistik melalui warna, tekstur, dan momen yang membeku dalam waktu.'),('id',5,'Pagi','Gambar berkualitas premium yang menampilkan keahlian dan perhatian terhadap detail.'),('tr',1,'Mükemmel','Renkler, dokular ve zamanda donmuş anlar aracılığıyla sanatsal bir yolculuk.'),('tr',2,'Yeni Gün','Modern tasarımın ve doğal güzelliğin özünü yakalayan çarpıcı bir görsel koleksiyonu.'),('tr',3,'Mutlu Gün','Ustalığı ve detaylara gösterilen özeni sergileyen premium kalitede görseller.'),('tr',4,'Doğa','Renkler, dokular ve zamanda donmuş anlar aracılığıyla sanatsal bir yolculuk.'),('tr',5,'Sabah','Ustalığı ve detaylara gösterilen özeni sergileyen premium kalitede görseller.'),('vi',1,'Hoàn Hảo','Hành trình nghệ thuật qua màu sắc, kết cấu và những khoảnh khắc đóng băng trong thời gian.'),('vi',2,'Ngày Mới','Bộ sưu tập hình ảnh tuyệt đẹp nắm bắt tinh hoa của thiết kế hiện đại và vẻ đẹp tự nhiên.'),('vi',3,'Ngày Vui','Hình ảnh chất lượng cao thể hiện tay nghề thủ công và sự chú ý đến từng chi tiết.'),('vi',4,'Thiên Nhiên','Hành trình nghệ thuật qua màu sắc, kết cấu và những khoảnh khắc đóng băng trong thời gian.'),('vi',5,'Buổi Sáng','Hình ảnh chất lượng cao thể hiện tay nghề thủ công và sự chú ý đến từng chi tiết.');
